// Generated by /ship test coverage audit.
// Value: protects=/api/external/* (skipped by the session gate) only answers with the exact X-API-Key, never 500s on a wrong-length key;
//   fails_when=router.use(requireExternalApiKey) is dropped/moved below routes, or the length guard before timingSafeEqual is removed;
//   why_new=apiAuthGate.test only proves /external/* bypasses the session gate; nothing exercises the key check; seam=none
import { describe, it, expect, jest, beforeAll, afterAll, afterEach } from '@jest/globals';
import express from 'express';
import type { Server } from 'http';
import type { AddressInfo } from 'net';

const mockGetAllProjects = jest.fn(async () => [{ id: 'p1' }]);
jest.mock('../../services/externalApiService', () => ({ externalApiService: { getAllProjects: mockGetAllProjects } }));
jest.mock('../../services/authService', () => ({ authService: { getUserFromToken: jest.fn(async () => null) } }));
jest.mock('../../services/selfHealService', () => ({ selfHealService: { captureIncident: jest.fn(async () => undefined) } }));
jest.mock('../../utils/logger', () => ({ logger: { error: jest.fn(), warn: jest.fn(), info: jest.fn() } }));

import { apiAuthGate } from '../../middleware/apiAuthGate';
import externalApiRoutes from '../../routes/externalApiRoutes';
import { errorHandler } from '../../middleware/errorHandler';

const KEY = 'k3y-0123456789abcdef';
const savedKey = process.env.EXTERNAL_API_KEY;
let server: Server;
let base: string;

beforeAll(async () => {
  const app = express();
  app.use('/api', apiAuthGate);
  app.use('/api/external', externalApiRoutes);
  app.use(errorHandler);
  await new Promise<void>((resolve) => { server = app.listen(0, '127.0.0.1', () => resolve()); });
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

afterAll(async () => {
  await new Promise<void>((resolve) => server.close(() => resolve()));
  if (savedKey === undefined) delete process.env.EXTERNAL_API_KEY; else process.env.EXTERNAL_API_KEY = savedKey;
});

afterEach(() => { process.env.EXTERNAL_API_KEY = KEY; });

const get = (path: string, key?: string) => fetch(`${base}${path}`, { headers: key === undefined ? {} : { 'X-API-Key': key } });

describe('/api/external API-key gate', () => {
  it.each([
    ['no key', undefined],
    ['wrong key of the same length', KEY.replace(/.$/, 'X')],
    ['shorter key', 'k3y'],
    ['longer key', `${KEY}-extra`],
    ['empty key', ''],
  ])('rejects %s with 401 and never reaches the data', async (_label, key) => {
    process.env.EXTERNAL_API_KEY = KEY;
    const res = await get('/api/external/projects', key);
    expect(res.status).toBe(401);
    expect(mockGetAllProjects).not.toHaveBeenCalled();
  });

  it('returns projects for the exact key', async () => {
    process.env.EXTERNAL_API_KEY = KEY;
    const res = await get('/api/external/projects', KEY);
    expect(res.status).toBe(200);
    expect(((await res.json()) as { data: unknown[] }).data).toEqual([{ id: 'p1' }]);
  });

  it('guards every path under the router, not just the routes that exist today', async () => {
    process.env.EXTERNAL_API_KEY = KEY;
    expect((await get('/api/external/anything-added-later')).status).toBe(401);
  });

  it('answers 503 (not open) when the key is unset or still a placeholder', async () => {
    delete process.env.EXTERNAL_API_KEY;
    expect((await get('/api/external/projects', '')).status).toBe(503);
    process.env.EXTERNAL_API_KEY = 'PASTE_YOUR_KEY';
    expect((await get('/api/external/projects', 'PASTE_YOUR_KEY')).status).toBe(503);
    expect(mockGetAllProjects).not.toHaveBeenCalled();
  });
});
